9	func mustConfig(t *testing.T, src string) *Config {
10		t.Helper()
11		cfg, f := ParseConfig([]byte(src))
12		if f != nil {
13			t.Fatalf("unexpected config failure: %+v", f)
14		}
15		return cfg
16	}
