31	const sampleConfig = `{
32	  "routes": [
33	    {"id": "api",    "methods": ["GET"],        "pathPrefix": "/api",         "upstream": "http://api.internal/v1"},
34	    {"id": "api-v2", "methods": ["*"],          "pathPrefix": "/api/v2",      "upstream": "https://api.internal:8443/v2"},
35	    {"id": "orders", "methods": ["GET", "POST"],"pathPrefix": "/api/orders", "upstream": "http://orders.internal"},
36	    {"id": "root",   "methods": ["*"],          "pathPrefix": "/",            "upstream": "https://fallback.internal/base/"},
37	    {"id": "users",  "methods": ["GET"],        "pathPrefix": "/users",       "upstream": "http://users.internal/u"}
38	  ]
39	}`
