398	func TestResolveConflict(t *testing.T) {
399		cfg := mustConfig(t, `{
400		  "routes": [
401		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://z.internal"},
402		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://a.internal"},
403		    {"id": "mid",   "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://m.internal"}
404		  ]
405		}`)
406		req, f := ParseRequest([]byte(`{"method":"GET","target":"/things"}`))
407		if f != nil {
408			t.Fatalf("unexpected request failure: %+v", f)
409		}
410		_, rf := Resolve(cfg, req)
411		if rf == nil {
412			t.Fatal("expected route_conflict")
413		}
414		if rf.Code != "route_conflict" {
415			t.Fatalf("code = %q, want route_conflict", rf.Code)
416		}
417		want := []string{"alpha", "mid", "zeta"}
418		if len(rf.Candidates) != len(want) {
419			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
420		}
421		for i := range want {
422			if rf.Candidates[i] != want[i] {
423				t.Fatalf("candidates = %v, want sorted %v", rf.Candidates, want)
424			}
425		}
426	
427		// Concrete vs wildcard at same prefix is NOT a conflict.
428		cfg2 := mustConfig(t, `{
429		  "routes": [
430		    {"id": "b-wild", "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://w.internal"},
431		    {"id": "a-get",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://g.internal"}
432		  ]
433		}`)
434		res := resolveJSON(t, cfg2, `{"method":"GET","target":"/things/x"}`)
435		if res.RouteID != "a-get" {
436			t.Fatalf("routeId = %q, want a-get", res.RouteID)
437		}
438	
439		// Two wildcards with no concrete entry remain a conflict.
440		cfg3 := mustConfig(t, `{
441		  "routes": [
442		    {"id": "w1", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w1.internal"},
443		    {"id": "w2", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w2.internal"}
444		  ]
445		}`)
446		_, rf = Resolve(cfg3, mustReq(t, "POST", "/things/x"))
447		if rf == nil || rf.Code != "route_conflict" {
448			t.Fatalf("got %+v, want route_conflict between wildcard routes", rf)
449		}
450	}
