452	// configFromRoutes builds a config document from raw route objects, so the
453	// same routes can be parsed in different orders.
454	func configFromRoutes(routes ...string) string {
455		return `{"routes":[` + strings.Join(routes, ",") + `]}`
456	}
457	
458	func reversed(routes []string) []string {
459		out := make([]string, len(routes))
460		for i, r := range routes {
461			out[len(routes)-1-i] = r
462		}
463		return out
464	}
