466	func TestResolveLongestPrefixBeatsShorterConcreteMethods(t *testing.T) {
467		// Selection order: longest prefix first, concrete-vs-wildcard only among
468		// the longest-prefix winners. A concrete GET on a shorter prefix must
469		// never override a wildcard on a longer prefix, and several GET routes
470		// tied on the shorter prefix must not conflict once the longer prefix
471		// wins.
472		routes := []string{
473			`{"id":"short-one","methods":["GET"],"pathPrefix":"/a","upstream":"http://one.internal/s1"}`,
474			`{"id":"short-two","methods":["GET"],"pathPrefix":"/a","upstream":"http://two.internal/s2"}`,
475			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/base"}`,
476		}
477	
478		cases := []struct {
479			name     string
480			request  string
481			upstream string
482		}{
483			{
484				name:     "longer wildcard beats shorter concrete GETs",
485				request:  `{"method":"GET","target":"/a/b/c/items"}`,
486				upstream: "http://wild.internal/base/c/items",
487			},
488			{
489				name:     "query string survives route selection verbatim",
490				request:  `{"method":"GET","target":"/a/b/c?keep=1&keep=2&empty=&x=%2f"}`,
491				upstream: "http://wild.internal/base/c?keep=1&keep=2&empty=&x=%2f",
492			},
493			{
494				name:     "target equal to the longer prefix keeps one junction slash",
495				request:  `{"method":"GET","target":"/a/b"}`,
496				upstream: "http://wild.internal/base/",
497			},
498			{
499				name:     "wildcard on the longer prefix also serves other methods",
500				request:  `{"method":"POST","target":"/a/b/c"}`,
501				upstream: "http://wild.internal/base/c",
502			},
503		}
504		for _, order := range [][]string{routes, reversed(routes)} {
505			cfg := mustConfig(t, configFromRoutes(order...))
506			for _, tc := range cases {
507				t.Run(tc.name, func(t *testing.T) {
508					res := resolveJSON(t, cfg, tc.request)
509					if res.RouteID != "long-wild" {
510						t.Errorf("routeId = %q, want long-wild", res.RouteID)
511					}
512					if res.UpstreamURL != tc.upstream {
513						t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
514					}
515				})
516			}
517		}
518	
519		// The shorter-prefix GET routes really are tied with each other: a
520		// request that only reaches their prefix does conflict, proving the
521		// longer prefix (not an absence of rivalry) is what decided the cases
522		// above.
523		cfg := mustConfig(t, configFromRoutes(routes...))
524		_, rf := Resolve(cfg, mustReq(t, "GET", "/a/c"))
525		if rf == nil || rf.Code != "route_conflict" {
526			t.Fatalf("got %+v, want route_conflict between the shorter-prefix GET routes", rf)
527		}
528		if want := []string{"short-one", "short-two"}; !equalStrings(rf.Candidates, want) {
529			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
530		}
531	}
