599	func TestResolveConflictOnlyAmongFinalCandidates(t *testing.T) {
600		// A conflict is reported only when the final candidates cannot be
601		// narrowed to one: shorter-prefix routes and same-prefix wildcard routes
602		// are already eliminated and must not appear in the candidate list, and
603		// no route may be returned as a success.
604		routes := []string{
605			`{"id":"z-short","methods":["GET"],"pathPrefix":"/a","upstream":"http://short.internal"}`,
606			`{"id":"wild-long","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal"}`,
607			`{"id":"zeta","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://z.internal"}`,
608			`{"id":"alpha","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://a.internal"}`,
609		}
610		for _, order := range [][]string{routes, reversed(routes)} {
611			cfg := mustConfig(t, configFromRoutes(order...))
612	
613			res, rf := Resolve(cfg, mustReq(t, "GET", "/a/b/x"))
614			if res != nil {
615				t.Fatalf("got success %+v, want route_conflict", res)
616			}
617			if rf == nil || rf.Code != "route_conflict" {
618				t.Fatalf("got %+v, want route_conflict", rf)
619			}
620			if want := []string{"alpha", "zeta"}; !equalStrings(rf.Candidates, want) {
621				t.Fatalf("candidates = %v, want %v (lexicographic, no shorter-prefix or wildcard routes)", rf.Candidates, want)
622			}
623	
624			// The wildcard route at the conflicted prefix still serves methods
625			// that have no concrete rival there.
626			res = resolveJSON(t, cfg, `{"method":"POST","target":"/a/b/x"}`)
627			if res.RouteID != "wild-long" {
628				t.Fatalf("POST: routeId = %q, want wild-long", res.RouteID)
629			}
630	
631			// The shorter-prefix route still serves requests that never reach
632			// the conflicted prefix.
633			res = resolveJSON(t, cfg, `{"method":"GET","target":"/a/other"}`)
634			if res.RouteID != "z-short" {
635				t.Fatalf("GET /a/other: routeId = %q, want z-short", res.RouteID)
636			}
637		}
638	}
