708					if f != nil {
709						t.Fatalf("unexpected failure: %+v", f)
710					}
711					return
712				}
713				if f == nil {
714					t.Fatalf("expected invalid_config containing %q", tc.want)
715				}
716				if f.Code != "invalid_config" {
717					t.Fatalf("code = %q, want invalid_config", f.Code)
718				}
719				if !strings.Contains(f.Reason, tc.want) {
720					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
721				}
722				if tc.located && !strings.Contains(f.Reason, "route ") {
