729	func TestInvalidConfigFieldTypes(t *testing.T) {
730		// Unlike TestInvalidConfig's missing/illegal-value cases, these exercise
731		// fields whose JSON type itself is wrong: valid JSON that cannot satisfy
732		// the field's type must still be invalid_config, but the reason has to
733		// name the route position (and a valid string id), distinguish it from a
734		// JSON syntax failure, and say why the field could not be read.
735		goodRoute := `"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"`
736	
737		cases := []struct {
738			name      string
739			src       string
740			want      []string // all must appear in the reason
741			forbidden []string // none may appear in the reason
742		}{
743			{
744				name: "methods string on second route, id after the bad field",
745				src: `{"routes":[
746				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
747				  {"methods":"GET","id":"orders","pathPrefix":"/api/orders","upstream":"http://o"}
748				]}`,
749				want: []string{"route 2", `"orders"`, "methods must be an array"},
750			},
751			{
752				name: "methods null",
753				src:  `{"routes":[{` + goodRoute + `,"methods":null}]}`,
754				want: []string{"route 1", `"x"`, "methods must be an array"},
755			},
756			{
757				name: "methods is an object",
758				src:  `{"routes":[{` + goodRoute + `,"methods":{"GET":true}}]}`,
759				want: []string{"route 1", `"x"`, "methods must be an array"},
760			},
761			{
762				name: "numeric entry inside a legal methods array",
763				src: `{"routes":[
764				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
765				  {"id":"orders","methods":["GET",1],"pathPrefix":"/api/orders","upstream":"http://o"}
766				]}`,
767				want: []string{"route 2", `"orders"`, "methods entry 2 must be a string"},
768			},
769			{
770				name: "null entry inside methods",
771				src:  `{"routes":[{` + goodRoute + `,"methods":[null]}]}`,
772				want: []string{"route 1", "methods entry 1 must be a string"},
773			},
774			{
775				name:      "id is a number",
776				src:       `{"routes":[{"id":1,"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
777				want:      []string{"route 1", "id must be a string"},
778				forbidden: []string{"(id "},
779			},
780			{
781				name:      "id is an object",
782				src:       `{"routes":[{"id":{"v":1},"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
783				want:      []string{"route 1", "id must be a string"},
784				forbidden: []string{"(id "},
785			},
786			{
787				name: "pathPrefix is a number, id written after it",
788				src:  `{"routes":[{"methods":["GET"],"pathPrefix":1,"id":"orders","upstream":"http://o"}]}`,
789				want: []string{"route 1", `"orders"`, "pathPrefix must be a string"},
790			},
791			{
792				name: "upstream is a boolean, id written after it",
793				src:  `{"routes":[{"methods":["GET"],"pathPrefix":"/a","upstream":true,"id":"orders"}]}`,
794				want: []string{"route 1", `"orders"`, "upstream must be a string"},
795			},
796			{
797				name: "routes entry is not an object",
798				src:  `{"routes":[42]}`,
799				want: []string{"route 1", "route entry must be an object", "got a number"},
800			},
801			{
802				name:      "null route entry is an element type error, not a missing id",
803				src:       `{"routes":[null]}`,
804				want:      []string{"route 1", "route entry must be an object", "got null"},
805				forbidden: []string{"id"},
806			},
807			{
808				name: "null route entry after a valid earlier route still rejects the config",
809				src: `{"routes":[
810				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
811				  null
812				]}`,
813				want:      []string{"route 2", "route entry must be an object", "got null"},
814				forbidden: []string{"id must"},
815			},
816		}
817		for _, tc := range cases {
818			t.Run(tc.name, func(t *testing.T) {
819				_, f := ParseConfig([]byte(tc.src))
820				if f == nil {
821					t.Fatalf("expected invalid_config")
822				}
823				if f.Code != "invalid_config" {
824					t.Fatalf("code = %q, want invalid_config", f.Code)
825				}
826				if strings.Contains(f.Reason, "not valid JSON") {
827					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
828				}
829				for _, want := range tc.want {
830					if !strings.Contains(f.Reason, want) {
831						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
832					}
833				}
834				for _, bad := range tc.forbidden {
835					if strings.Contains(f.Reason, bad) {
836						t.Fatalf("reason = %q must not contain %q", f.Reason, bad)
837					}
838				}
839			})
840		}
841	
842		// Broken JSON syntax stays a parse failure and never gets a guessed
843		// route position, even when the document opens with a routes field,
844		// contains a complete first route, or is corrupt inside the array.
845		for _, src := range []string{
846			`{not json`,
847			`{"routes": [{"id":"x"} broken`,
848			`{"routes":[ broken`,
849			`{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}] broken`,
850		} {
851			_, f := ParseConfig([]byte(src))
852			if f == nil || f.Code != "invalid_config" {
853				t.Fatalf("got %+v, want invalid_config for %q", f, src)
854			}
855			if !strings.Contains(f.Reason, "not valid JSON") {
856				t.Fatalf("reason = %q, want a JSON parse failure", f.Reason)
857			}
858			if strings.Contains(f.Reason, "route 1") || strings.Contains(f.Reason, "must be a JSON object") ||
859				strings.Contains(f.Reason, "routes must") {
860				t.Fatalf("syntax failure must not guess a shape or route position: %q", f.Reason)
861			}
862		}
863	
864		// Fixing the second route's methods lets the request resolve normally,
865		// including through the first route it originally matched.
866		cfg := mustConfig(t, `{"routes":[
867		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
868		  {"id":"orders","methods":["GET"],"pathPrefix":"/api/orders","upstream":"http://orders.internal"}
869		]}`)
870		res := resolveJSON(t, cfg, `{"method":"GET","target":"/api/items"}`)
871		if res.RouteID != "api" || res.UpstreamURL != "http://api.internal/v1/items" {
872			t.Fatalf("got %+v, want api / http://api.internal/v1/items", res)
873		}
874	}
