494	// TestResolveCLIRequestErrorReasons exercises how malformed requests are
495	// explained at the command boundary: broken JSON is a parse failure, a legal
496	// non-object document says the request must be an object, and a legal object
497	// with a wrong-typed field names the field and the received type. Every
498	// failure still exits non-zero, leaves stdout empty and emits one JSON error.
499	func TestResolveCLIRequestErrorReasons(t *testing.T) {
500		cases := []struct {
501			name      string
502			request   string
503			want      []string
504			forbidden []string
505		}{
506			{
507				name:      "syntactically broken JSON",
508				request:   `{"method":"GET",`,
509				want:      []string{"not valid JSON"},
510				forbidden: []string{"method", "target"},
511			},
512			{
513				name:      "top level array is legal JSON but the wrong shape",
514				request:   `["GET","/api"]`,
515				want:      []string{"must be a JSON object"},
516				forbidden: []string{"not valid JSON"},
517			},
518			{
519				name:      "top level null is legal JSON but the wrong shape",
520				request:   `null`,
521				want:      []string{"must be a JSON object"},
522				forbidden: []string{"not valid JSON"},
523			},
524			{
525				name:      "numeric method is a field type error",
526				request:   `{"method":42,"target":"/api"}`,
527				want:      []string{"method must be a string", "got a number"},
528				forbidden: []string{"not valid JSON"},
529			},
530			{
531				name:      "array target is a field type error",
532				request:   `{"method":"GET","target":[]}`,
533				want:      []string{"target must be a string", "got an array"},
534				forbidden: []string{"not valid JSON", "start with /"},
535			},
536			{
537				name:      "null method is a type error, not a missing method",
538				request:   `{"method":null,"target":"/api"}`,
539				want:      []string{"method must be a string", "got null"},
540				forbidden: []string{"method is required"},
541			},
542			{
543				name:      "both fields wrong report method regardless of key order",
544				request:   `{"target":[],"method":42}`,
545				want:      []string{"method must be a string"},
546				forbidden: []string{"target must be a string"},
547			},
548			{
549				name:      "empty string is content validated, not type checked",
550				request:   `{"method":"GET","target":"/api%2"}`,
551				want:      []string{"invalid percent escape"},
552				forbidden: []string{"must be a string"},
553			},
554		}
555		for _, tc := range cases {
556			t.Run(tc.name, func(t *testing.T) {
557				res := runResolveCLI(t, cliSuccessConfig, tc.request)
558				if res.exitCode == 0 {
559					t.Fatalf("exit code = 0, want non-zero")
560				}
561				if len(res.stdout) != 0 {
562					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
563				}
564				var fail struct {
565					Code   string `json:"code"`
566					Reason string `json:"reason"`
567				}
568				decodeOneJSON(t, res.stderr, "stderr", &fail)
569				if fail.Code != "invalid_request" {
570					t.Fatalf("code = %q, want invalid_request", fail.Code)
571				}
572				for _, want := range tc.want {
573					if !strings.Contains(fail.Reason, want) {
574						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
575					}
576				}
577				for _, bad := range tc.forbidden {
578					if strings.Contains(fail.Reason, bad) {
579						t.Errorf("reason = %q must not contain %q", fail.Reason, bad)
580					}
581				}
582			})
583		}
584	
585		// A bad config is reported before the request is even examined, so a
586		// broken config paired with a broken request still yields invalid_config.
587		badConfig := `{"routes":[{"id":"x","methods":"GET","pathPrefix":"/a","upstream":"http://h"}]}`
588		res := runResolveCLI(t, badConfig, `{not json`)
589		if res.exitCode == 0 || len(res.stdout) != 0 {
590			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
591		}
592		var fail struct {
593			Code string `json:"code"`
594		}
595		decodeOneJSON(t, res.stderr, "stderr", &fail)
596		if fail.Code != "invalid_config" {
597			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
598		}
599	}
