824		// alpha and zeta both concretely accept GET at the same /api prefix
825		// with no longer prefix to win; the same-prefix wildcard route must not
826		// appear among the final candidates.
827		config := `{
828		  "routes": [
829		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
830		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
831		    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
832		  ]
833		}`
834		res := runResolveCLI(t, config, cliSuccessRequest)
835	
836		if res.exitCode == 0 {
837			t.Fatalf("exit code = 0, want non-zero")
838		}
839		if len(res.stdout) != 0 {
840			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
841		}
842	
843		var fail struct {
844			Code       string   `json:"code"`
845			Reason     string   `json:"reason"`
846			Candidates []string `json:"candidates"`
847		}
848		decodeOneJSON(t, res.stderr, "stderr", &fail)
849		if fail.Code != "route_conflict" {
850			t.Errorf("code = %q, want route_conflict", fail.Code)
851		}
852		if fail.Reason == "" {
853			t.Fatal("reason must be non-empty")
854		}
855		wantCandidates := []string{"alpha", "zeta"}
856		if !reflect.DeepEqual(fail.Candidates, wantCandidates) {
857			t.Errorf("candidates = %v, want %v (sorted, wildcard excluded)", fail.Candidates, wantCandidates)
858		}
859	}
