		return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
	}
	if u.Host == "" {
		return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
	}
	if f := validateBracketedUpstreamHost(u, loc, id); f != nil {
		return f
	}
	return nil
}

// validateBracketedUpstreamHost requires an IP-literal host to be a legal
// IPv6 address: square brackets are an IP literal delimiter, so the content
// must be a valid IPv6 address, never an ordinary registered name or a bare
// IPv4 address. Unbracketed hosts (domains and bare IPv4) are left untouched.
// The content is compared after url unescaping so an encoded zone separator
// (%25) and other legal host encodings are recognized, while malformed
// percent escapes are rejected. Empty brackets and any malformed IPv6 address
// fail the whole configuration as invalid_config, naming the route position,
// its id and the upstream field.
func validateBracketedUpstreamHost(u *url.URL, loc, id string) *Failure {
	host := u.Host
	if i := strings.IndexByte(host, ']'); i >= 0 {
		host = host[:i]
	}
	open := strings.IndexByte(host, '[')
	if open < 0 {
		return nil
	}
	literal := host[open+1:]
	addr, err := url.PathUnescape(literal)
	if err != nil {
		return failuref("invalid_config",
			"%s (id %q): upstream %q: bracketed host is not a valid IPv6 address", loc, id, literal)
	}
	parsed, err := netip.ParseAddr(addr)
	if err != nil || !parsed.Is6() {
		return failuref("invalid_config",
			"%s (id %q): upstream %q: bracketed host is not a valid IPv6 address", loc, id, literal)
	}
	return nil
}

