func TestResolveCLIBracketedHostRequiresIPv6(t *testing.T) {
	for _, tc := range []struct {
		name    string
		bad     string
		literal string
	}{
		{"ordinary name", "http://[not-an-ip]/v1", "not-an-ip"},
		{"bare ipv4", "http://[127.0.0.1]:8080/v1", "127.0.0.1"},
		{"empty brackets", "http://[]/v1", ""},
